SELECT id, openid, unionid, username, nickname, phone, wechat_id, avatar_url, status, create_time, last_modify_time FROM kitchen_user WHERE 1 = 1
AND status = #{status}
AND ( nickname ILIKE CONCAT('%', #{keyword}, '%') OR username ILIKE CONCAT('%', #{keyword}, '%') OR phone ILIKE CONCAT('%', #{keyword}, '%') OR wechat_id ILIKE CONCAT('%', #{keyword}, '%') )
ORDER BY create_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM kitchen_user WHERE 1 = 1
AND status = #{status}
AND ( nickname ILIKE CONCAT('%', #{keyword}, '%') OR username ILIKE CONCAT('%', #{keyword}, '%') OR phone ILIKE CONCAT('%', #{keyword}, '%') OR wechat_id ILIKE CONCAT('%', #{keyword}, '%') )
